declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Database;use App\Services\LiveDisplaySessionService;$pdo=Database::connection();$token=trim((string)($_GET['token']??''));$session=LiveDisplaySessionService::byToken($pdo,$token);if(!$session){http_response_code(404);exit('Live Display link is invalid or disabled.');}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Live Display</title><style>html,body{margin:0;width:100%;height:100%;background:#000;overflow:hidden}iframe{display:block;width:100vw;height:100vh;border:0;background:#000}</style></head><body><iframe id="feed" title="BDC Live Display Feed" allow="fullscreen"></iframe><script>const token=<?=json_encode($token)?>,feed=document.querySelector('#feed');let fingerprint='',timerFingerprint='',pageTimer=null,busy=false;function loadFeed(s){const fp=[s.state_version,s.data_version||0,s.screen_type,s.round_id,s.page_number,s.reveal_place].join('|');if(fp!==fingerprint){fingerprint=fp;const endpoint=s.screen_type==='winners'&&!s.reveal_place?'podium-ready.php':s.screen_type==='final_results'?'final-relative-placement.php':'feed.php';feed.src=endpoint+'?token='+encodeURIComponent(token)+'&v='+encodeURIComponent(fp)+'&_='+Date.now()}const tf=[s.auto_page,s.page_delay_seconds,s.total_pages,s.screen_type].join('|');if(tf===timerFingerprint)return;timerFingerprint=tf;clearInterval(pageTimer);if(!s.loop_enabled&&s.auto_page&&s.total_pages>1&&['competitors','callbacks','finalists'].includes(s.screen_type)){pageTimer=setInterval(async()=>{try{await fetch('advance.php?token='+encodeURIComponent(token)+'&_='+Date.now(),{method:'POST',cache:'no-store'});await tick()}catch(e){}},Number(s.page_delay_seconds)*1000)}}async function tick(){if(busy)return;busy=true;try{const r=await fetch('state.php?token='+encodeURIComponent(token)+'&_='+Date.now(),{cache:'no-store'}),s=await r.json();if(s&&s.ok)loadFeed(s)}catch(e){}finally{busy=false}}tick();setInterval(tick,700);</script></body></html>
